pedjasapp-liberty/src/main/java/com/pedjas/entity/Producto.java<pre><code>package com.pedjas.entity;

import javax.persistence.Entity;
import javax.persistence.GeneratedValue;
import javax.persistence.GenerationType;
import javax.persistence.Id;
import javax.persistence.NamedQueries;
import javax.persistence.NamedQuery;
import javax.persistence.Table;
import javax.persistence.Column;

/**
 * Entidad JPA — reemplaza el EJB 2.x CMP ProductoBean.
 * Compatible con WebSphere Liberty mediante la feature jpa-2.2.
 */
@Entity
@Table(name = "PRODUCTOS")
@NamedQueries({
    @NamedQuery(
        name  = "Producto.findAll",
        query = "SELECT p FROM Producto p ORDER BY p.nombre"
    ),
    @NamedQuery(
        name  = "Producto.findByCategoria",
        query = "SELECT p FROM Producto p WHERE p.categoria = :categoria"
    )
})
public class Producto {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    @Column(name = "ID")
    private Long id;

    @Column(name = "NOMBRE", nullable = false, length = 100)
    private String nombre;

    @Column(name = "DESCRIPCION", length = 500)
    private String descripcion;

    @Column(name = "PRECIO", nullable = false)
    private Double precio;

    @Column(name = "CATEGORIA", length = 50)
    private String categoria;

    // Constructores
    public Producto() {}

    public Producto(String nombre, Double precio, String categoria) {
        this.nombre    = nombre;
        this.precio    = precio;
        this.categoria = categoria;
    }

    // Getters y setters
    public Long getId()                    { return id; }
    public void setId(Long id)             { this.id = id; }

    public String getNombre()              { return nombre; }
    public void setNombre(String nombre)   { this.nombre = nombre; }

    public String getDescripcion()         { return descripcion; }
    public void setDescripcion(String d)   { this.descripcion = d; }

    public Double getPrecio()              { return precio; }
    public void setPrecio(Double precio)   { this.precio = precio; }

    public String getCategoria()           { return categoria; }
    public void setCategoria(String c)     { this.categoria = c; }
}
</code></pre>

